import{_ as a,o as i,c as e,a5 as t}from"./chunks/framework.0V7P45eC.js";const k=JSON.parse('{"title":"Command line: dedupe, join and clean CSV files","description":"Remove near-duplicate rows, match two spreadsheets, rename columns and search a CSV or JSON file from the terminal with npx, no code.","frontmatter":{"title":"Command line: dedupe, join and clean CSV files","description":"Remove near-duplicate rows, match two spreadsheets, rename columns and search a CSV or JSON file from the terminal with npx, no code."},"headers":[],"relativePath":"recipes/cli.md","filePath":"recipes/cli.md","lastUpdated":1795827637000}'),n={name:"recipes/cli.md"};function l(h,s,p,o,d,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to &quot;Command line&quot;">​</a></h1><p>Dedupe a customer export, match two spreadsheets, or try a score, without writing code. Works with <code>npx</code>, nothing to install.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="clean-a-messy-export-end-to-end" tabindex="-1">Clean a messy export, end to end <a class="header-anchor" href="#clean-a-messy-export-end-to-end" aria-label="Permalink to &quot;Clean a messy export, end to end&quot;">​</a></h2><p><em><code>map-fields</code> since 2.8.0, <code>standardize</code> since 2.9.0.</em></p><p>Commands read from standard input with <code>-</code>, so they chain. This export has French headers, cities and companies typed three ways, and the same people twice:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span>Prénom;NOM;E-mail;Ville;Société</span></span>
<span class="line"><span>Ada;Lovelace;ada@x.io;Paris;ACME Inc</span></span>
<span class="line"><span>ada;lovelace;ada@x.io;paris;Acme</span></span>
<span class="line"><span>Alan;Turing;alan@y.io;Londres;Globex Ltd</span></span>
<span class="line"><span>Grace;Hopper;grace@z.io;Pariss;acme inc.</span></span>
<span class="line"><span>Alan;Turing;alan@y.io;londres;Globex</span></span></code></pre></div><p>Rename the columns, give each city and company one spelling, then keep one row per email:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> map-fields</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> export.csv</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> firstName,lastName,email,city,company</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> standardize</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> city</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> company</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> inc</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> ltd</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> dedupe</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> email</span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> clean.csv</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span>firstName;lastName;email;city;company</span></span>
<span class="line"><span>Ada;Lovelace;ada@x.io;Paris;ACME Inc</span></span>
<span class="line"><span>Alan;Turing;alan@y.io;Londres;Globex Ltd</span></span>
<span class="line"><span>Grace;Hopper;grace@z.io;Paris;ACME Inc</span></span></code></pre></div><p>The separator of the file (here <code>;</code>, as Excel writes it in French) is kept. What each step changed goes to the terminal, not to the file.</p><h2 id="input-and-output" tabindex="-1">Input and output <a class="header-anchor" href="#input-and-output" aria-label="Permalink to &quot;Input and output&quot;">​</a></h2><ul><li><strong>CSV</strong>, with commas, semicolons (Excel in French) or tabs, detected from the first line. The first line holds column names.</li><li><strong>JSON</strong>: an array of strings or of objects.</li><li><strong>Plain text</strong>: one item per line.</li><li><code>-</code> reads standard input.</li></ul><p>Results are written to standard output in the same format, so you can redirect them: <code>&gt; clean.csv</code>. Add <code>--json</code> for JSON.</p><h2 id="remove-duplicates" tabindex="-1">Remove duplicates <a class="header-anchor" href="#remove-duplicates" aria-label="Permalink to &quot;Remove duplicates&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> dedupe</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> customers.csv</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> sarl</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> sas</span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> clean.csv</span></span></code></pre></div><p><code>-k</code> names the column to compare (the first one by default; repeat it to use several). <code>-i</code> ignores a word, such as a legal form. The first row of each group of near-duplicates is kept.</p><p>To review before deleting, <code>group</code> adds a <code>group</code> column instead: rows with the same number are duplicates of each other.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> group</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> customers.csv</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> name</span></span></code></pre></div><h2 id="match-two-files" tabindex="-1">Match two files <a class="header-anchor" href="#match-two-files" aria-label="Permalink to &quot;Match two files&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> orders.csv</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> customers.csv</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --left-key</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> client</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --right-key</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --unique</span></span></code></pre></div><p>Each row of <code>orders.csv</code> gets the columns of its best match in <code>customers.csv</code>, plus a <code>score</code> column. Rows with no match keep empty columns. <code>--unique</code> uses each customer at most once. Right columns with the same name as a left column are prefixed with <code>right_</code>.</p><h2 id="one-spelling-per-value" tabindex="-1">One spelling per value <a class="header-anchor" href="#one-spelling-per-value" aria-label="Permalink to &quot;One spelling per value&quot;">​</a></h2><p><em>Since 2.9.0.</em></p><p><code>standardize</code> rewrites a column with the most common spelling of each value: &quot;paris&quot;, &quot;PARIS&quot; and &quot;Pariss&quot; become &quot;Paris&quot;. Repeat <code>-k</code> for several columns; how many values changed goes to the terminal.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> standardize</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> contacts.csv</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> city</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> company</span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> clean.csv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># city: 41 values changed</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># company: 7 values changed</span></span></code></pre></div><h2 id="rename-columns-to-your-names" tabindex="-1">Rename columns to your names <a class="header-anchor" href="#rename-columns-to-your-names" aria-label="Permalink to &quot;Rename columns to your names&quot;">​</a></h2><p><em>Since 2.8.0.</em></p><p>A CSV export never names its columns like your code does. <code>map-fields</code> renames them, reading camelCase, snake_case and synonyms (zip and postal code, prénom and first name), and puts them in your order:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> map-fields</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> export.csv</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> firstName,lastName,email,postalCode</span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> clean.csv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Prénom -&gt; firstName</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># E-mail -&gt; email</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Zip -&gt; postalCode</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># not found, left empty: lastName</span></span></code></pre></div><p>What was renamed goes to the terminal, the file to standard output. Columns that match none of your names are kept at the end (<code>--drop</code> leaves them out), and <code>--to</code> also takes a <code>.json</code> file: an array of names or a JSON Schema.</p><h2 id="search-and-compare" tabindex="-1">Search and compare <a class="header-anchor" href="#search-and-compare" aria-label="Permalink to &quot;Search and compare&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> &quot;bohemian rapsody&quot;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> songs.csv</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> title</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> artist</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> 5</span></span>
<span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> fuzzy-toolkit</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> compare</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> &quot;beyonsay&quot;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> &quot;Beyoncé&quot;</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --phonetic</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Effect</th></tr></thead><tbody><tr><td><code>-k, --key &lt;column&gt;</code></td><td>Column holding the text. Repeatable.</td></tr><tr><td><code>--left-key</code>, <code>--right-key</code></td><td><code>join</code>: columns of each file.</td></tr><tr><td><code>--unique</code></td><td><code>join</code>: use each right row at most once.</td></tr><tr><td><code>-t, --threshold &lt;0-100&gt;</code></td><td>Minimum score (default 80).</td></tr><tr><td><code>-p, --preset &lt;name&gt;</code></td><td><code>music</code>, <code>search</code> or <code>strict</code>.</td></tr><tr><td><code>--phonetic</code></td><td>Also match texts that sound the same.</td></tr><tr><td><code>-i, --ignore &lt;word&gt;</code></td><td>Word to ignore. Repeatable.</td></tr><tr><td><code>-l, --limit &lt;n&gt;</code></td><td><code>search</code>: maximum number of results (default 10).</td></tr><tr><td><code>--json</code></td><td>Write JSON.</td></tr></tbody></table>`,35)])])}const F=a(n,[["render",l]]);export{k as __pageData,F as default};
